insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('80c70ca8-f07f-597e-bfbb-b1f9bb4c29ba', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice completes the text with the most logical and precise word or phrase?', '["enrich", "avoid", "predict", "deny"]'::jsonb, 1, 'The success of the Mission District Murals in San Francisco, California—a collection of murals that reflect the area’s Latino heritage and cultural history—exemplifies how collaborative art initiatives can ______ their communities in multiple ways, including enhancing public spaces and addressing local issues.'),
  ('7a2dbda8-4403-5b9b-ac21-e029d15f7ac1', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice completes the text with the most logical and precise word or phrase?', '["differentiated from", "surpassed by", "elevated from", "explored by"]'::jsonb, 2, 'Blue holes, such as the Great Blue Hole and Watling’s Blue Hole, are deep sinkholes that form underwater. Because the dark blue appearance of their waters means these pits can be easily ______ shallow areas around them, where the water looks light blue, many blue holes have been discovered by people doing recreational activities like boating.'),
  ('6f8780ca-21ef-5ee6-b42e-821ba874eba5', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice completes the text with the most logical and precise word or phrase?', '["obviating", "extolling", "necessitating", "rescinding"]'::jsonb, 3, 'Commercial truck drivers sometimes transport temperature-sensitive goods like fresh produce through a variety of external conditions that can affect temperatures inside cargo areas, ______ the use of specialized equipment to continuously and automatically monitor and adjust refrigeration settings to prevent the goods from spoiling.'),
  ('b4929bbb-035b-5930-a5d0-aec33f751ffd', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice completes the text with the most logical and precise word or phrase?', '["interpret", "hasten", "transform", "overshadow"]'::jsonb, 4, 'By eliminating middlemen, direct-to-consumer sales channels allow small farms to capture retail prices rather than accept lower wholesale rates. The pricing advantages that come with adopting this model, combined with the customer loyalty that comes from forging personal connections, can ______ the financial outlook for many small agricultural producers.'),
  ('613c6530-f8e8-554c-8866-dfa5b6f447a4', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice best states the main purpose of the text?', '["To discuss the widespread impact of the invention of the automobile", "To detail how cities changed their roads to accommodate motor vehicles", "To argue that technological progress can have unintended negative effects", "To explain how the earliest automobiles worked"]'::jsonb, 5, 'Before the invention of the automobile, personal transportation options typically consisted of riding on horseback or in horse-drawn carriages at slow speeds. When the automobile became widely available in the early 20th century, however, its influence extended far beyond just how people traveled. This invention affected society on many levels. It connected previously isolated communities, changed city layouts, and gave individuals unprecedented freedom of movement.'),
  ('5f6de833-1695-5dc7-9cd8-85e85323c805', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice best describes the overall structure of the text?', '["It explains how one cultural institution was founded, then explains its plans to expand further.", "It discusses one cultural institution, then discusses a more recently founded cultural institution.", "It defines a certain type of cultural institution, then argues that this type of institution decisively influences society.", "It describes a trend among cultural institutions in the United States, then identifies an institution that rejects that trend."]'::jsonb, 6, 'Founded in Denver in 1991, the Museo de Las Americas is dedicated to art from Latin America, including the art of Indigenous peoples. Since its founding, it has acquired more than 4,800 objects for its permanent collection. More recently founded US-based institutions devoted to Latino cultures include the National Museum of Puerto Rican Arts and Culture. Located in Chicago, it focuses on the arts and culture of Puerto Rico and of Chicago’s Puerto Rican community.'),
  ('191ba4d9-17e1-5397-9305-38b0213a8091', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '["It summarizes a shift in scientists’ understanding of how Sparus aurata has responded to ocean acidification.", "It elaborates on a potential consequence of Pimentel and colleagues’ reliance on a relatively small sample size.", "It emphasizes the magnitude of the effect reported by Pimentel and colleagues of ocean acidification on Sparus aurata.", "It counters the objection of Clark and colleagues to studies that rely on relatively small sample sizes."]'::jsonb, 7, 'In 2016 Marta S. Pimentel and colleagues published a study concluding that ocean acidification has a strong effect on the behavior of Sparus aurata, a species of fish. However, Pimentel and colleagues’ study relied on a mean sample size of only 12 fish. In a 2022 review of various scientists’ conclusions about the impacts of ocean acidification on fish behavior, Timothy D. Clark and colleagues caution that relying on such a relatively small sample size can increase the potential for biased analysis. <u>Such</u> <u>analysis, in turn, can contribute to reports of exaggerated effects.</u>'),
  ('5ea468d2-9301-556e-8636-7f107a76cb0e', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'What does the text indicate is a benefit of the information collected by participants in the Urban Wildlife Information Network?', '["It informs city planning and conservation efforts.", "It inspires tourists to visit metropolitan areas.", "It identifies which animal species are becoming extinct.", "It ranks the popularity of green spaces with city residents."]'::jsonb, 8, 'Through the Urban Wildlife Information Network, citizen scientists systematically document animals they observe in metropolitan areas. Participants record not just which species they see but also the species’ behaviors and nearby urban features, such as artificial lighting, buildings, and green spaces. The resulting database helps researchers understand how animals adapt to human-dominated landscapes and informs city planning and conservation efforts that benefit both people and wildlife.'),
  ('11eac498-b9b8-52bf-a97b-4e97ab447a65', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which statement about data set J72T12G24 is best supported by the text?', '["The data set consists primarily of real manufacturing data collected from industrial settings, supplemented with simulated scenarios to fill gaps in production patterns.", "The data set represents the most frequently encountered manufacturing scenarios, assigning more significance to the most commonly occurring combinations of demand patterns, capacity utilization, and cost balances.", "The data set was structured to primarily target unusual manufacturing conditions, including low production capacity utilization and fluctuating demand patterns.", "The data set was designed to ensure coverage of a range of hypothetical manufacturing situations in order to effectively teach the machine learning model."]'::jsonb, 9, 'Researchers created data set J72T12G24 to train a machine learning model to select the best existing algorithm for determining manufacturers’ optimal production quantities while considering capacity constraints and other limiting factors. Comprising 7,200 simulated production planning instances, each involving seventy-two products across twelve time periods, the data set systematically varies three critical factors: product demand patterns (six scenarios, including fluctuating demand), production capacity utilization rates (high and low), and the balance between set-up and inventory holding costs (three scenarios).'),
  ('6ae8190c-14c0-5ec2-91fd-ed471d43bb3d', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which quotation from Poems most effectively illustrates the claim?', '["“Our world, so worn and weary, / Needs music, pure and strong, / To hush the jangle and discords / Of sorrow, pain, and wrong.” (from “Songs for the People”)", "“Let me make the songs for the people, / Songs for the old and young; / Songs to stir like a battle-cry / Wherever they are sung.” (from “Songs for the People”)", "“Welcome children of the Spring, / In your garbs of green and gold, / Lifting up your sun-crowned heads / On the verdant plain and wold.” (from “Dandelions”)", "“Only a little scrap of blue / Preserved with loving care, / But earth has not a brilliant hue / To me more bright and fair.” (from “A Little Child Shall Lead Them”)"]'::jsonb, 10, 'Poems is an 1895 collection of poetry by Frances E.W. Harper. In one of Harper’s poems, the speaker declares her intention to create art that has a universal appeal across generations, saying, ______'),
  ('a463bfc6-a97b-5d61-ad1d-5a9327c09c5d', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice best describes data from the graph that weaken the student’s claim?', '["Although agricultural exports from Mexico decreased over the five years before NAFTA, a reversal in this trend was observed over the five years after Mexico joined NAFTA.", "All the countries shown had positive growth in agricultural exports over the five years after joining their respective FTAs, but their rates of export growth varied.", "Although agricultural exports from Morocco grew over the five years after Morocco joined MAFTA, their growth rate was even higher in the five years before MAFTA.", "Over the five years after Costa Rica joined CAFTA-DR, agricultural exports from Costa Rica grew at a rate of about 13.5 percent, which is higher than the rate over the five years before Costa Rica joined the agreement."]'::jsonb, 11, '![figure](/q/sep26/001.webp)

To measure whether countries in free trade agreements (FTAs)—agreements among nations to reduce tariffs, duties, and other trade barriers—experience changes in total agricultural exports, economist Kayode Ajewole and colleagues calculated average export growth rates for several countries over the five years before and the five years after entering an FTA with the United States. The graph shows the results for three countries in the study. Consulting the graph, a student claims that joining an FTA increases the rate of growth of a country’s total agricultural exports.'),
  ('39af12c9-d28a-5005-a2b7-0babd68b0917', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which quotation from The Age of Innocence best illustrates the claim?', '["“[T]hinking over a pleasure to come often gave [Newland] a subtler satisfaction than its realisation.”", "“When Newland Archer opened the door at the back of the club box the curtain had just gone up on the garden scene. There was no reason why the young man should not have come earlier, for he had dined at seven, alone with his mother and sister.”", "“It surprised [Newland] that life should be going on in the old way when his own reactions to it had so completely changed.”", "“It was Madame Nilsson’s first appearance [in an opera] that winter, and what the daily press had already learned to describe as ‘an exceptionally brilliant audience’ had gathered to hear her.”"]'::jsonb, 12, 'The Age of Innocence is a 1920 novel by Edith Wharton set in New York City in the 1870s. In the novel, Newland Archer arrives late to an opera performance, which the narrator attributes to Newland’s enjoyment of anticipation: ______'),
  ('a0dc0904-d714-55f7-b7a4-fe5f9ef0c1e1', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which statement, if true, would best illustrate the student’s claim in the underlined text?', '["Jansson resigned from creating a daily Moomin comic strip in 1959 after working on it for seven years, and her brother Lars took her place.", "Jansson was an intensely private person but still responded personally to thousands of letters from fans writing about the Moomins.", "Jansson created her own magazine when she was thirteen years old and sold copies of it at her school.", "Jansson wrote Moominsummer Madness and other Moomin stories but also published many memorable political cartoons."]'::jsonb, 13, 'The writer and illustrator of Moominsummer Madness (1970) and many other Moomin stories for children didn’t initially set out to be known as a children’s author. While Tove Jansson accomplished a great deal as a painter and cartoonist, she became widely popular as the creator of the Moomin characters she is still best remembered for today—Moomintroll, Gaffsie, and other eccentric figures. A student who is researching children’s literature asserts that <u>even though this outcome wasn’t what Jansson had</u> <u>intended, she committed to the role she found herself in.</u>'),
  ('5d451a09-9b7e-5358-a0f4-2f450a9cb15a', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice most logically completes the text?', '["lowest among participants who were fans of Led Zeppelin.", "higher than those for songs without syncopation.", "lower than those for “Smells Like Teen Spirit.”", "highest among participants who were fans of Nirvana."]'::jsonb, 14, 'In a study of groove (defined as the degree to which participants wanted to move with the music), researchers expected that a song with a moderate-complexity rhythm, such as “Kashmir” by Led Zeppelin, would elicit higher groove ratings than would a song with a low-complexity rhythm, such as “Smells Like Teen Spirit” by Nirvana. This hypothesis was based on findings about a specific form of rhythmic complexity known as syncopation (when beats played in the rhythm deviate from the steady, underlying pulse of a song), which suggested that moderate syncopation was associated with the highest groove ratings. Contrary to the hypothesis, the groove ratings participants gave for “Kashmir” were generally ______'),
  ('2717373e-6157-51fa-be9c-bcadbd5c7650', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice most logically completes the text?', '["ignore the predator-prey relationships between large and small mammals.", "reflect factors affecting large mammals other than increasing human activity.", "exaggerate the effect of increasing human activity on small mammals.", "overestimate the actual population sizes of large mammals."]'::jsonb, 15, 'Scientists recently created a model to predict how increasing human activity will affect future mammal population sizes in US national forests. Unfortunately, when the model is applied to large forests, its predictions for large-mammal populations are too high, and when applied to small forests, its predictions for small-mammal populations are too high. Beaverhead-Deerlodge National Forest in Montana is a large forest, covering more than 3 million acres. If used to evaluate the effect of increasing human activity on this forest in ten years, the model would likely therefore ______'),
  ('39a40fd0-17ec-5722-976b-716135315f33', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["shape", "shaped", "shaping", "shapes"]'::jsonb, 16, 'Japanese bonsai artist Masashi Hirao has crafted an approach that transforms the acts of pruning, wiring, and planting into dynamic public performances. Audiences are entertained as they watch his creative process unfold, with Hirao rhythmically ______ trees to music.'),
  ('32ffca54-dd26-5455-b9f3-8361300305b0', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["street’s and neighborhoods", "streets and neighborhoods", "street’s and neighborhood’s", "streets and neighborhood’s"]'::jsonb, 17, 'The history of Los Angeles can be read in the numerous ______ that memorialize historical figures like Isaac Newton Van Nuys, Hedy Lamarr, and Laffit Pincay Jr. with place names like Van Nuys, Lamarr Avenue, and Pincay Drive.'),
  ('19240121-1ca0-5580-b01a-54d795cd1832', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["volume the shesep, a unit of length", "volume, the shesep; a unit of length,", "volume; the shesep; a unit of length;", "volume; the shesep, a unit of length;"]'::jsonb, 18, 'Writing in hieroglyphs, ancient Egyptians recorded measurements using units such as the khar, a unit of ______ and the sa, a unit of area. The khar, for instance, is written as a circular hieroglyph with horizontal lines running across it.'),
  ('a992a792-baaa-5935-888c-f574ef925370', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["compounds,", "compounds—", "compounds", "compounds;"]'::jsonb, 19, 'In 1856, nineteen-year-old chemist William Perkin attempted to synthesize artificial quinine from coal tar, an industrial waste product that, because of its availability and recently discovered amino ______ offered an economical alternative to expensive natural quinine extracted from tropical tree bark. Perkin’s failed experiments instead produced a brilliant purple solution that launched the synthetic dye industry.'),
  ('7b1c3352-9480-5d0a-89bb-97d84af215ca', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["1959, Harbour developed by Antonio Linares in 1999; and Clojure", "1959; Harbour, developed by Antonio Linares in 1999; and Clojure,", "1959, Harbour; developed by Antonio Linares in 1999; and Clojure,", "1959; Harbour, developed by Antonio Linares in 1999, and Clojure,"]'::jsonb, 20, 'The programming languages COBOL, developed by Grace Hopper in ______ developed by Rich Hickey in 2007, are all routinely translated into executable code by tools known as compilers.'),
  ('263381c7-1d9b-52c3-be20-000a14d8f2ef', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Ulysses, stamping all 4,311 “-ing” verbs onto individual corks.That", "Ulysses. Stamping all 4,311 “-ing” verbs onto individual corks that", "Ulysses, stamping all 4,311 “-ing” verbs onto individual corks that", "Ulysses by stamping all 4,311 “-ing” verbs onto individual corks that"]'::jsonb, 21, 'For her 2010 installation “Dubling,” Brazilian artist Elida Tessler extracted every gerund from James Joyce’s novel ______ capped empty wine bottles and creating 4,311 postcards featuring images of Dublin’s River Liffey, she forged a visual connection between the flowing waters so central to Joyce’s narrative and the novel’s stream-of-consciousness style.'),
  ('0ba41437-ddb7-5588-913f-9a70f0db7899', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice completes the text with the most logical transition?', '["Afterward,", "For example,", "Instead,", "However,"]'::jsonb, 22, 'In ancient Rome, eligible citizens would gather in public squares to vote for their leaders on election day. ______ the winning candidates would take office and begin making important decisions for the city.'),
  ('e25b41e0-391c-56f0-ae4d-4c743c6299ff', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice completes the text with the most logical transition?', '["In summary,", "Instead of that,", "As this occurs,", "As one example,"]'::jsonb, 23, 'When air near Earth’s surface is heated, it becomes less dense and rises upward. ______ cooler, denser air sinks downward, creating a circular movement of air called a convection current.'),
  ('11951c39-30bc-59ee-8e19-d65ff099582d', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice completes the text with the most logical transition?', '["On the contrary, a pollutant such as chromium can be removed from the soil;", "Moreover, the plant is potentially useful in removing accumulated metals;", "For this reason, the plant has useful applications in soil quality restoration;", "That said, the plant may not always be able to remove all of the pollutant;"]'::jsonb, 24, 'Plant species known as metal hyperaccumulators can help remove heavy metal pollutants from soil. Cyperus rotundus, or purple nutsedge, for instance, can absorb a large quantity of chromium and store it safely in its roots and shoots. ______ its roots may not reach far enough into the soil and could leave trace amounts of chromium.'),
  ('7e6e1fdd-0c26-5c05-8323-61e47896837e', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice completes the text with the most logical transition?', '["By contrast,", "Similarly,", "Consequently,", "Nevertheless,"]'::jsonb, 25, 'On November 20, 2013, Malta’s government lowered the minimum voting age for its citizens from 18 to 16 years old. ______ many young people in Malta gained a new opportunity to participate in their country’s political process.'),
  ('7e13a382-8317-5a45-a73a-e26fe904dc33', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'Which choice completes the text with the most logical transition?', '["In reality,", "As a result,", "In other words,", "Similarly,"]'::jsonb, 26, 'It’s tempting to think that the chaotic scene depicted in Joseph Heintz the Younger’s painting Competition on the Ponte dei Pugni in Venice (1673) could only have existed in the artist’s imagination: a bridge is covered with dozens of brawling men, some tumbling into the canal below, and throngs of excited spectators crowd the sidewalks, gondolas, and windows of surrounding buildings. ______ such dramatic competitions between rival neighborhood factions were regular occurrences in seventeenth-century Venice.'),
  ('ce09a885-3b4f-5ad8-afac-d7325d1fc02b', '2ec99b6b-15b7-5867-a2e5-c1efd1666a23', 'The student wants to present a finding from the study. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Participants were asked to identify the correct version of Pikachu, who is a creature with markings at the base of its tail.", "In a 2021 study, researchers asked participants to identify the correct version of Pikachu.", "Pikachu is a creature with markings at the base of its tail, but in one of the altered versions, the creature had markings at the tip of its tail.", "When participants were asked to identify the correct version of Pikachu, 26.8% selected the unaltered image."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

In a 2021 study, researchers showed participants an unaltered image of a popular character or logo alongside two slightly altered versions.
Pikachu is a creature with markings at the base of its tail.
In the first alteration, the creature had markings at the tip of its tail.
In the second alteration, the creature’s tail had no markings.
Participants were asked to identify the correct version.
26.8% of participants selected the unaltered image.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('80c70ca8-f07f-597e-bfbb-b1f9bb4c29ba', 0, null, 'Public art that improves spaces and addresses issues improves its communities: "enrich."'),
  ('7a2dbda8-4403-5b9b-ac21-e029d15f7ac1', 0, null, 'The dark blue water makes the holes easy to tell apart from the light blue shallows: "differentiated from."'),
  ('6f8780ca-21ef-5ee6-b42e-821ba874eba5', 2, null, 'Changing external conditions make continuous monitoring equipment required: "necessitating."'),
  ('b4929bbb-035b-5930-a5d0-aec33f751ffd', 2, null, 'Better prices plus customer loyalty can greatly change the farms'' finances: "transform."'),
  ('613c6530-f8e8-554c-8866-dfa5b6f447a4', 0, null, 'The text explains how the automobile affected society on many levels.'),
  ('5f6de833-1695-5dc7-9cd8-85e85323c805', 1, null, 'It describes the Museo de Las Americas, then a more recently founded museum.'),
  ('191ba4d9-17e1-5397-9305-38b0213a8091', 1, null, 'It explains what the small sample could lead to: biased analysis and exaggerated effects.'),
  ('5ea468d2-9301-556e-8636-7f107a76cb0e', 0, null, 'The database "informs city planning and conservation efforts."'),
  ('11eac498-b9b8-52bf-a97b-4e97ab447a65', 3, null, 'The simulated instances systematically vary three factors to cover many situations for training.'),
  ('6ae8190c-14c0-5ec2-91fd-ed471d43bb3d', 1, null, '"Songs for the old and young" expresses art meant for all generations.'),
  ('a463bfc6-a97b-5d61-ad1d-5a9327c09c5d', 2, null, 'Morocco''s export growth was higher before MAFTA (19.6%) than after (4.9%), which contradicts the claim.'),
  ('39af12c9-d28a-5005-a2b7-0babd68b0917', 0, null, 'The quotation says anticipating a pleasure often satisfied Newland more than the pleasure itself.'),
  ('a0dc0904-d714-55f7-b7a4-fe5f9ef0c1e1', 1, null, 'Though private, she personally answered thousands of Moomin fan letters: she embraced the role.'),
  ('5d451a09-9b7e-5358-a0f4-2f450a9cb15a', 2, null, 'Contrary to the hypothesis, the moderately complex song rated lower than the low-complexity one.'),
  ('2717373e-6157-51fa-be9c-bcadbd5c7650', 3, null, 'For large forests the model overpredicts large-mammal populations.'),
  ('39a40fd0-17ec-5722-976b-716135315f33', 2, null, '"with Hirao rhythmically shaping trees" is a with-phrase that needs a participle.'),
  ('32ffca54-dd26-5455-b9f3-8361300305b0', 1, null, 'Plural nouns "streets and neighborhoods," no possessives needed.'),
  ('19240121-1ca0-5580-b01a-54d795cd1832', 3, null, 'List items contain commas, so semicolons separate them: "volume; the shesep, a unit of length;".'),
  ('a992a792-baaa-5935-888c-f574ef925370', 0, null, 'The comma closes the phrase opened after "that" ("because of... compounds,").'),
  ('7b1c3352-9480-5d0a-89bb-97d84af215ca', 1, null, 'List items with internal commas are separated by semicolons; "Clojure, developed..." needs a comma.'),
  ('263381c7-1d9b-52c3-be20-000a14d8f2ef', 1, null, 'A new sentence begins with the participial phrase whose subject is "she."'),
  ('0ba41437-ddb7-5588-913f-9a70f0db7899', 0, null, 'Taking office comes after the election: "Afterward."'),
  ('e25b41e0-391c-56f0-ae4d-4c743c6299ff', 2, null, 'The cool air sinks at the same time as warm air rises: "As this occurs."'),
  ('11951c39-30bc-59ee-8e19-d65ff099582d', 3, null, 'After praising the plant, the text notes a limitation: "That said."'),
  ('7e6e1fdd-0c26-5c05-8323-61e47896837e', 2, null, 'Lowering the voting age gave young people a new opportunity: "Consequently."'),
  ('7e13a382-8317-5a45-a73a-e26fe904dc33', 0, null, 'Though it seems imaginary, such fights really happened: "In reality."'),
  ('ce09a885-3b4f-5ad8-afac-d7325d1fc02b', 3, null, 'It states the finding: only 26.8% picked the unaltered image.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

