  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('cc09d74a-bd6e-5a48-92f2-2ac5512584bb', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice completes the text with the most logical and precise word or phrase?', '["sanitized", "estimated", "populated", "precluded"]'::jsonb, 1, 'Lady Grant and colleagues ______ pots of sterilized soil with slurries of live microbes collected from soil in five sites across Colorado, including areas of sagebrush and ponderosa pine forest. Grant and team then grew mustard plants in the pots to see if the different microbial slurries affected levels of spicy glucosinolates like indole in the plants’ seeds.'),
  ('2d79eb70-b4f3-5e49-b9c5-2b771f35aeda', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice completes the text with the most logical and precise word or phrase?', '["fraudulent", "byzantine", "rudimentary", "monotonous"]'::jsonb, 2, 'Electricians confronting century-old wiring often find themselves playing detective, tracing circuits that were modified numerous times by different hands, each addressing—with varying levels of sophistication—immediate needs with little effort to maintain overall organization. What appears to be a simple fixture replacement can reveal a network that is truly ______.'),
  ('6b5ca6cb-a8c1-5dc7-b3b3-9c2b57431576', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice completes the text with the most logical and precise word or phrase?', '["shallowness", "rigor", "novelty", "obscurity"]'::jsonb, 3, 'The dinosaur displays at museums such as the American Museum of Natural History in New York (which has a mounted Allosaurus fragilis skeleton among its holdings) are notable for the ______ of the research behind them—the museum staff consulted numerous sources to ensure the accuracy of the displays.'),
  ('93f6d0e3-cc27-538e-a16f-8bff36ee859e', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice completes the text with the most logical and precise word or phrase?', '["pragmatic", "ambivalent", "enigmatic", "impulsive"]'::jsonb, 4, 'While some of the Mediterranean islands inhabited by prehistoric peoples were rich in resources and easily accessible from the mainland, others were resource-poor and could only be reached by grueling, hazardous, multiday voyages in rowboats. The motivations of the people who settled the latter are thus, from our modern perspective, ______.'),
  ('04ece30a-4578-5995-9484-bf89f6b8ef53', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'As used in the text, what does the word “lament” most nearly mean?', '["Regret", "Expect", "Repudiate", "Enumerate"]'::jsonb, 5, 'The following text is adapted from Virginia Woolf’s 1919 novel Night and Day.

In times gone by, Mrs. Hilbery had known all the poets, all the novelists. These being now either dead or secluded in their infirm glory, she made her house a meeting-place for her own relations, to whom she would lament the passing of the great days of the nineteenth century, when every department of letters and art was represented in England by two or three illustrious names.'),
  ('5a1cd314-dbde-5635-aac4-837434f07cbb', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice best states the main purpose of the text?', '["To compare two experiments addressing the same questions", "To describe difficulties associated with preserving seeds", "To discuss an ongoing experiment", "To explain how to get rid of certain plants"]'::jsonb, 6, 'In 1879, in an effort to determine the longevity of certain seeds left in soil, botanist William Beal buried 20 glass bottles filled with sand and seeds from a variety of plants, including Verbascum, Lepidium virginicum, and Oenothera biennis.

Since then, some of the bottles have been retrieved in the periodic checks of seed viability researchers are conducting. After 60 years had elapsed, most of the seeds in those bottles stopped germinating, but Verbascum seeds have remained viable, including those from a bottle dug up in 2021 by Margaret Fleming, David Lowry, and colleagues.'),
  ('afe3e42c-c651-5930-b26f-2064c3ae759c', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice best states a shared purpose of Text 1 and Text 2?', '["To suggest that the distinctive aesthetics of certain traditional needlework techniques both reflect and transcend these techniques’ functional origins", "To trace how two decorative forms of sewing influenced the development of certain utilitarian mending techniques that prioritize strength", "To evaluate the increasingly prevalent practice of incorporating visible mending techniques into the design of new clothing and textiles", "To highlight the complexity of the patterns that can emerge through the repetition of simple stitches in traditional needlework techniques"]'::jsonb, 7, '**Text 1**

Along with techniques such as darning and patching, the time-honored Japanese craft of sashiko emphasizes rather than obscures repairs and has become a popular form of visible mending (which conserves natural resources used in clothing production by extending the life cycle of textiles).

In seigaiha (wave) and other traditional patterns, repeated stitches of thick thread form striking geometric motifs that contribute to both the strength and the beauty of everyday textiles.

**Text 2**

Generally less ornate than phulkari embroidery and other forms of decorative South Asian needlework, kantha originated in northeastern India as a practical technique in which straight, parallel lines of visible stitching join layers of cloth, covering holes and renewing fragile or worn material. Some contemporary Indian designers value kantha for its visual appeal, adapting this technique to adorn high-end garments.'),
  ('d5ca5590-d01b-55bd-ba5c-f2b3bcb1f9f6', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Based on the text, what can be concluded about clothing made during the Ice Age?', '["Clothing made with awls at sites like Mladeč likely had coarser seams than clothing made with needles at sites like Ust-Kova did.", "Clothing made with awls at sites like Mladeč could likely be made more quickly than clothing made with needles at sites like Ust-Kova.", "Clothing made at sites like Mladeč was likely made with needles, while clothing made at sites like Ust-Kova was likely made with awls.", "Clothing made with awls at sites like Mladeč likely had finer seams than clothing made with needles at sites like Ust-Kova did."]'::jsonb, 8, 'Ian Gilligan et al. claim that during the Ice Age, humans at Mladeč in Europe made fitted clothing by boring holes in pieces of hide and fur with a sharpened bone tool called an awl and then threading cord through the holes to bind the pieces together. Eventually, as evidenced by artifacts at Ust-Kova in Siberia, someone perforated the end of a bone awl to make an eye (hole) to hold the cord, thereby creating a sewing needle with which both steps could be performed in a single motion. This sped up the process of making clothing and, by freeing them from the need to push cord through holes manually, allowed artisans to make smaller holes and thus finer seams.'),
  ('01f5571f-1111-53ca-9bff-6a6deb17a3c8', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Based on the text, Ang would most likely agree with which statement about initiatives such as the implementation of restrictions on personal gain by public officeholders?', '["They should not be regarded as having independent causes but rather as being the shared result of capitalist growth.", "They cannot be explained simply as either a precondition of capitalist growth or a consequence of capitalist growth.", "They show more variation across polities in their relationship to economic development than some theories suggest.", "They are overemphasized by both developmental-state theory and modernization theory."]'::jsonb, 9, 'Pointing to the rapid economic development of Japan and other polities under market capitalism, advocates of developmental-state theory hold that legal constraints on personal enrichment by public officeholders and other bureaucratic initiatives enable growth.

Citing cases as distinct as the United States and Mauritius, proponents of modernization theory hold the inverse, that so-called Weberian bureaucracies emanate from capitalist growth. Yuen Yuen Ang has recently argued that both positions presume linear causality in situations in which neither phenomenon is truly independent of the other.'),
  ('b29ff383-6738-59e3-bac0-880368ffe13f', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Taken together, the text and graph best support which conclusion about 2-methyl-1,3-butadiene?', '["Although the compound’s emission deters most hornworms, a small percentage of hornworms appear insensitive to the compound and will consume leaves that emit it.", "Although the compound’s emission does not entirely prevent leaf consumption by hornworms, its emission is associated with reduced leaf consumption.", "Although leaves emit the compound in response to insect feeding, it does not appear to significantly reduce leaf consumption by hornworms.", "Although the compound is toxic to hornworms, the insects will consume leaves that emit it even when leaves that don’t emit it are available."]'::jsonb, 10, '![figure](/q/sep26/002.webp)

Some plants’ leaves emit a chemical compound (2-methyl-1,3-butadiene) that is thought to be a defense against insects. Researchers modified leaves of the same plant species so that some emitted the compound and others didn’t, then placed hornworms—leaf-eating insects—between leaves of both types and allowed the hornworms to feed for 90 minutes.'),
  ('0e46324f-b5f8-5192-a8eb-e023993c98b8', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which finding, if true, would most directly support the researcher’s claim?', '["Current users of the SPRINTER are satisfied with the number of stops along the line.", "Residents of Oceanside, California, are much less likely to use public transit on rainy days than on clear days.", "The enforcement of posted speed limits in the neighborhood that the light rail stop will service has increased substantially in the last ten years.", "There has been a sharp increase in the last ten years in cyclists who use the roads in the neighborhood that the light rail stop will service."]'::jsonb, 11, 'A team of public transportation experts in Oceanside, California, is creating a new light rail stop for the SPRINTER system that will service a neighborhood in which a stop does not currently exist. To decide where to place the stop, the team is using a survey from ten years ago that asked how far neighborhood residents would be willing to walk to a light rail stop. The team also looked at studies showing that people’s willingness to walk to public transit is influenced by factors like weather and the presence of well-enforced low speed limits for cars. A researcher has argued that the survey does not accurately reflect the feelings of today’s residents of this neighborhood.'),
  ('609492a1-ff6d-5180-a2b6-b60484877bbc', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice most effectively uses data from the table to complete the assertion?', '["the average male wing centroid size was 1.98 mm in May but was 2.31 mm in June.", "the average female wing centroid size was smaller in May than in July.", "the average male wing centroid size was consistently smaller than the average female wing centroid size in all four months in the table.", "the average monthly low temperature was lower in May than in June."]'::jsonb, 12, '**Monthly Temperatures and Wing Centroid Sizes of Fruit Fly Specimens**

| Month | Average high (°F) | Average low (°F) | Average male wing centroid size (mm) | Average female wing centroid size (mm) |
| June | 80 | 56 | 2.01 | 2.31 |
| October | 67 | 44 | 1.98 | 2.29 |
| July | 87 | 62 | 2.02 | 2.31 |
| May | 73 | 50 | 1.98 | 2.27 |

Drosophila (fruit flies) have generation times of 10-12 days, so seasonal changes in humidity and other environmental conditions can drive seasonal fluctuations in chromosome rearrangements in species such as D. robusta and D. subobscura. Drosophila body size (for which wing centroid size serves as a proxy measure) correlates with reproductive fitness. Banu Şebnem Önder and Cansu Fidan Aksoy measured the wing sizes of members of a D. melanogaster population in Yeşilöz, Turkey, that were collected monthly between May and October over three years. Their research suggests that Drosophila collected in relatively cooler months should tend to have lower reproductive fitness, as is illustrated by the finding that ______'),
  ('b22e95c3-4a66-5404-a150-bd67986cc4d6', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice most logically completes the text?', '["patterns of electricity use are shaped in part by consumer discretion.", "the use of DRS will guarantee that the supply of electricity remains sufficient.", "increased reliance on renewable energy will be possible in the future.", "the success of DRS will prompt other nations to develop renewable energy sources."]'::jsonb, 13, 'Countries whose electricity grids are heavily dependent on renewable energy—Colombia, for instance, obtains over 65% of its energy from such sources—often struggle to meet consumer demand during peak hours (times of the day when electricity use is very high).

Concerns about electrical supply limitations have led some nations to utilize demand-response systems (DRS) that motivate consumers to change habits through lower electricity prices during off-peak hours. These efforts reflect an assumption that ______'),
  ('ac5d2a7f-4397-5f38-a11e-d85dd41cd0ce', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice most logically completes the text?', '["Y. evonymella and A. caja likely exhibit a form of protective mimicry in which distinct species with chemical defenses develop a nearly identical signal to repel predators.", "Y. evonymella is an example of a phenomenon in which palatable species gain protection from predators by resembling or mimicking unpalatable or otherwise well-defended species.", "like certain moths in the Arctiinae family, several species of moths belonging to the genus Yponomeuta produce ultrasonic pulses to communicate noxiousness rather than to disrupt bat echolocation.", "in both small-bodied and large-bodied moths, acoustic aposematic signaling is more prevalent than previous studies of defenses against bat predation had suggested."]'::jsonb, 14, 'To combat predation by Arizona myotis (Myotis occultus) and other insectivorous bats, some moth species—including Euchaetes egle, a moth native to North America—have evolved the ability to produce ultrasonic pulses that, for instance, disrupt the echolocation bats rely on to forage in low-light conditions or, alternatively, serve as aposematic signals (warning of toxicity or distastefulness).

David J.L. Agassiz et al. found that Yponomeuta evonymella, a species of small-bodied moths that produces noxious substances, emits ultrasonic pulses that closely resemble the acoustic aposematic signals of Arctia caja, a noxious moth species in the large-bodied Arctiinae family whose distribution overlaps with that of Y. evonymella. The researchers therefore concluded that ______'),
  ('5e7345f2-1f8f-5686-a224-b1e7f43db9b3', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice most logically completes the text?', '["probate inventories from 1600 to 1750 that have been analyzed by scholars exaggerated the number of consumer goods that relatively prosperous individuals possessed.", "scholars’ previous conclusions based on analysis of probate inventories from 1600 to 1750 overstated broader demographic shifts in the possession of consumer goods.", "advocates of the consumer-revolution argument may have failed to account for the possibility that the increased acquisition of consumer goods in England between 1600 and 1750 was attributable to an increase in the proportion of wealthy individuals in the period.", "wage increases in England between 1600 and 1750 did not account for the widespread acquisition of consumer goods among less-wealthy individuals."]'::jsonb, 15, 'Support for the argument that a “consumer revolution,” in which possession of consumer goods among an increasingly wide range of socioeconomic groups surged despite only marginal wage growth, occurred in England between 1600 and 1750 has largely hinged on scholars’ analyses of probate inventories (detailed legal records of deceased persons’ possessions).

Reexamining these data, Gregory Clark notes that while inventories from the period appear consistent with the consumer-revolution argument, the proportion of the population whose wills included such documentation decreased considerably between 1600 and 1750, with this documentation increasingly representing more affluent individuals. Clark’s findings thus directly raise the possibility that ______'),
  ('2fc2e3a7-dc19-527e-80f9-7c1284a9a4f1', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["2003, revolutionizing the field of economic research, before", "2003. Revolutionizing the field of economic research before", "2003, revolutionizing the field of economic research. Before", "2003, revolutionizing the field of economic research before"]'::jsonb, 16, 'Angus Maddison’s The World Economy: Historical Statistics includes estimated total market values for the world’s largest economies dating back to 1 CE. This comprehensive resource was first published in ______ its release, gaps in historical records hindered researchers’ ability to analyze economic trends across centuries.'),
  ('7a1d937d-a75f-5ab8-a161-5475e5e7dae7', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["future lexicographers considered the dictionary, which preserved knowledge of the Hopi language, as a model.", "the dictionary’s preservation of knowledge of the Hopi language was considered a model for future lexicographers.", "knowledge of the Hopi language was preserved by the dictionary, which was considered a model for future lexicographers.", "the dictionary preserved knowledge of the Hopi language and was considered a model for future lexicographers."]'::jsonb, 17, 'Emory Sekaquaptewa, a Hopi anthropologist and lexicographer, helped compile a bilingual Hopi-English dictionary published in 1998. Containing almost 30,000 entries, ______'),
  ('3ebae10c-4b1d-5c8d-905c-c954df8868b4', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["handwriting", "handwriting,", "handwriting-which", "handwriting;"]'::jsonb, 18, 'Early electronic telecommunications systems, like telegraphy, could only transmit basic text. The facsimile (or fax) system, developed in the 1980s, coupled rapid message transmission with the ability to accurately render formatting and ______ in legal transactions, for example, signed documents could now be transmitted across continents in minutes.'),
  ('6145976b-8cb7-590c-ab83-01321e0ee82f', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["example. With", "example with", "example and with", "example, with"]'::jsonb, 19, 'Within Earth’s biomes, there are four main types of desert: arid, semiarid, coastal, and cold. The Sahara Desert in northern Africa is an arid desert, for ______ a total area of about 9,200,000 km², it is also one of the largest deserts of any type.'),
  ('50e66864-fc6b-54dc-9722-1a7209abad7a', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["indicating", "indicates", "can indicate", "will indicate"]'::jsonb, 20, 'Metagenomic analysis of chewed tree pitch unearthed at Sweden’s Huseby Klev archaeological site has revealed concrete information about Mesolithic humans’ dietary practices, the DNA analysis ______ consumption of hazelnuts, red deer, fish from the salmon family, and various bird species.'),
  ('b7d752a3-672a-5477-b831-14a095676af8', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["will form", "form", "forming", "can form"]'::jsonb, 21, 'The process by which Colombian emeralds are created depends on specialized geological conditions, the gems typically ______ as hydrothermal fluids interact with carbon-rich black shales.'),
  ('954d367a-08ad-5566-9e2d-b06e70668c71', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice completes the text with the most logical transition?', '["Moreover,", "For instance,", "Admittedly,", "By contrast,"]'::jsonb, 22, 'At the Museum of Natural History in Washington, DC, a single specimen of the planktonic marine organism T. iota is preserved as the reference organism for the species. This specimen is a holotype, meaning it was the basis of the first formal scientific description of T. iota. ______ the reference organism for the planktonic G. truncatulinoides, preserved at the Natural History Museum in London, is a neotype, meaning it acts as a reference organism but is not the exact specimen originally described.'),
  ('65df9f17-c807-5ffc-a1ac-2755f097b62f', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice completes the text with the most logical transition?', '["for example,", "likewise,", "that is,", "in contrast,"]'::jsonb, 23, 'Whereas humans have trichromatic vision (a function of having three types of cone cells in the retina), birds have tetrachromatic vision; ______ birds have a fourth type of cone cell in their retinas, one sensitive to ultraviolet (UV) light, which allows them to see UV-reflective patterns in plumage that reveal male-female distinctions invisible to human eyes.'),
  ('0b69f034-faf7-574a-9ddb-b9669488f2ed', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'Which choice completes the text with the most logical transition?', '["however,", "similarly,", "in sum,", "consequently,"]'::jsonb, 24, 'Photogrammetry, used by digital artists to develop 3D assets for video games, yields objects with precise mathematical proportions. Granted, as they are formed from perfect geometric shapes, such 3D elements lack organic realism; ______ post-modeling processes such as UV surface mapping are needed to achieve the level of verisimilitude gamers expect.'),
  ('bce5ca47-42ca-53ec-be1c-d53b089fdada', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'The student wants to emphasize a similarity between the two films. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["In Alf’s Button (1930), actress Merle Oberon played a nameless, uncredited role; however, in Désirée (1954), she played a credited role—that of Empress Josephine.", "Early in her career, Merle Oberon wasn’t listed in some film credits, such as the credits for the film Alf’s Button, where she played a nameless, uncredited role.", "Alf’s Button (1930) was released early in actress Merle Oberon’s career, whereas Désirée (1954) came out later.", "Alf’s Button and Désirée are both films that include Merle Oberon, the first Indian-born actress to be nominated for an Academy Award."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

Merle Oberon (1911-1979) was an actress born in Mumbai (then known as Bombay), India. She was of Indian, Maori, and Irish heritage.
She was the first Indian-born actress to be nominated for an Academy Award.
Early in her career, she played many nameless, uncredited roles, such as her role in Alf’s Button (1930).
Later, she played many named, credited roles, such as Empress Josephine in Désirée (1954).'),
  ('27849df0-d64f-5305-b522-7f5f1ad16041', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'The student wants to distinguish Bourne’s proposed theory from Bigelow’s. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["In contending with the truth-maker objection, ersatz presentism diverges from Lucretianism’s use of past-tensed properties by positing an “ersatz” time-outside-time capable of representing past things.", "Following Bigelow’s 1996 proposal, Bourne accepted the existence of past-tensed properties to solve the truth-maker problem with one caveat: a form of “ersatz” time that exists outside temporal time.", "The presentist approaches of Bigelow (1996) and Bourne (2006) differ in whether they consider truths about the past—the statement “dinosaurs existed,” for example—to be made true by anything at all.", "In 2006, Bourne proposed ersatz presentism, disagreeing with Bigelow’s earlier hypothesis that only present things exist."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Philosophers espousing presentism (the view that only present things exist) must contend with the truth-maker objection (TO).
TO: If past things don’t exist, what makes true statements about the past (e.g., “dinosaurs existed”) true? 1996: Presentist philosopher John Bigelow proposed “Lucretianism.”
Lucretianism posits that the statement is made true by the world’s acceptance of the past-tensed property of “having contained dinosaurs.”
2006: Presentist philosopher Craig Bourne proposed “ersatz presentism.” Ersatz presentism posits that the statement is made true by an abstract (“ersatz”) time that exists outside temporal time and represents how things were in the past.'),
  ('6664ebb0-54bd-5f71-8ba3-de0476b2b903', '69458d15-d9e2-5d5f-8f57-d1f46a8bd746', 'The student wants to make and support a claim about the LNF rock art style based on Motta et al.’s study. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The distinct style displayed by the LNF rock art forms a bridge between the styles of the earlier IIAP animal figures and the later Gwion representations of humans.", "The LNF rock art should be considered its own distinct style because its depictions of animal forms reveal a categorical departure from the art of the previous period.", "The differences between the LNF rock art and earlier IIAP depictions of animals show a notable increase in detail and variety, proving that rock art figures became more detailed over time.", "The study by Motta et al. showed that the LNF figures were clearly layered in between anthropomorphic figures of distinct styles that took place millennia apart."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Prehistoric rock art in the Kimberley region of Australia consists of several distinct styles across various time periods.
Irregular Infill Animal Period (IIAP) rock art from 13,000 to 17,000 years ago consists of naturalistic animal figures showing detailed features and a variety of poses.
Gwion rock art from 12,000 to 14,000 years ago features elaborately ornamented anthropomorphic figures.
Wanjina rock art from up to 5,000 years ago features human ancestor figures along with animal motifs.
A 2025 study of Kimberley rock art by Ana Paula Motta et al. identified 98 figures depicting outlines of animal forms with simple anatomical details and posed predominantly in profile.
The study’s superimposition analysis showed that these Linear Naturalistic Figures (LNF) consistently appear on top of Gwion and underneath Wanjina figures.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('cc09d74a-bd6e-5a48-92f2-2ac5512584bb', 2, null, 'The sterile pots were filled with live microbes: "populated."'),
  ('2d79eb70-b4f3-5e49-b9c5-2b771f35aeda', 1, null, 'Circuits altered many times without organization form an intricate, convoluted network: "byzantine."'),
  ('6b5ca6cb-a8c1-5dc7-b3b3-9c2b57431576', 1, null, 'Staff consulted many sources to ensure accuracy: the "rigor" of the research.'),
  ('93f6d0e3-cc27-538e-a16f-8bff36ee859e', 2, null, 'Why anyone would risk such voyages for poor islands is hard to understand: "enigmatic."'),
  ('04ece30a-4578-5995-9484-bf89f6b8ef53', 0, null, 'She mourned the passing of the great days: "regret."'),
  ('5a1cd314-dbde-5635-aac4-837434f07cbb', 2, null, 'The text describes Beal''s seed experiment, which researchers are still checking.'),
  ('afe3e42c-c651-5930-b26f-2064c3ae759c', 0, null, 'Both show stitching that began as practical repair but is valued for its beauty.'),
  ('d5ca5590-d01b-55bd-ba5c-f2b3bcb1f9f6', 0, null, 'Needles allowed smaller holes and finer seams, so awl-made clothing had coarser seams.'),
  ('01f5571f-1111-53ca-9bff-6a6deb17a3c8', 1, null, 'Ang says neither causes the other in a simple line, so such rules are neither just a precondition nor just a result of growth.'),
  ('b29ff383-6738-59e3-bac0-880368ffe13f', 1, null, 'Emitting leaves lost less area than nonemitting leaves in every trial, but they were still eaten.'),
  ('0e46324f-b5f8-5192-a8eb-e023993c98b8', 2, null, 'Much stricter speed-limit enforcement would change residents'' willingness to walk since the survey.'),
  ('609492a1-ff6d-5180-a2b6-b60484877bbc', 1, null, 'May was cooler than July, and the female wing size was smaller in May (2.27 vs 2.31 mm).'),
  ('b22e95c3-4a66-5404-a150-bd67986cc4d6', 0, null, 'Price incentives assume consumers can choose when they use electricity.'),
  ('ac5d2a7f-4397-5f38-a11e-d85dd41cd0ce', 0, null, 'Both moths are noxious and share a similar warning signal: mutual mimicry between defended species.'),
  ('5e7345f2-1f8f-5686-a224-b1e7f43db9b3', 1, null, 'The inventories increasingly covered only the wealthy, so a society-wide rise may be overstated.'),
  ('2fc2e3a7-dc19-527e-80f9-7c1284a9a4f1', 2, null, 'The participial phrase ends the first sentence; "Before its release" starts a new one.'),
  ('7a1d937d-a75f-5ab8-a161-5475e5e7dae7', 3, null, '"Containing almost 30,000 entries" must describe the dictionary.'),
  ('3ebae10c-4b1d-5c8d-905c-c954df8868b4', 3, null, 'A semicolon joins two independent clauses.'),
  ('6145976b-8cb7-590c-ab83-01321e0ee82f', 0, null, '"for example" ends the first sentence; a new sentence begins "With a total area..."'),
  ('50e66864-fc6b-54dc-9722-1a7209abad7a', 0, null, '"the DNA analysis indicating..." is an absolute phrase after the comma.'),
  ('b7d752a3-672a-5477-b831-14a095676af8', 2, null, '"the gems typically forming..." is an absolute phrase after the comma.'),
  ('954d367a-08ad-5566-9e2d-b06e70668c71', 3, null, 'A neotype contrasts with the holotype just described: "By contrast."'),
  ('65df9f17-c807-5ffc-a1ac-2755f097b62f', 2, null, 'The sentence explains what tetrachromatic means: "that is."'),
  ('0b69f034-faf7-574a-9ddb-b9669488f2ed', 3, null, 'Because the shapes lack realism, extra processing is needed: "consequently."'),
  ('bce5ca47-42ca-53ec-be1c-d53b089fdada', 3, null, 'It states what the films share: both include Merle Oberon.'),
  ('27849df0-d64f-5305-b522-7f5f1ad16041', 0, null, 'It contrasts Bourne''s "ersatz" time with Bigelow''s past-tensed properties.'),
  ('6664ebb0-54bd-5f71-8ba3-de0476b2b903', 1, null, 'LNF depicts animals while the earlier Gwion art shows human-like figures, supporting it as a distinct style.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
