insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('8860cd01-f1b9-5cf4-94a2-2b469baa5229', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'What is the area, in square centimeters, of a rectangle with a length of $52$ centimeters and a width of $37$ centimeters?', '["$1,924$", "$1,820$", "$89$", "$178$"]'::jsonb, 1, null),
  ('adbb25bd-baa8-5464-82c5-73bb4601d732', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'The function $f$ is defined by $f(x) = 7x - 4$. What is the value of $f(x)$ when $x = 80$?', '[]'::jsonb, 2, null),
  ('295bef8a-e569-5a30-b3da-07b5c74a8627', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'Each face of a fair 18-sided die is labeled with a number from $1$ through $18$, with a different number appearing on each face. If the die is rolled one time, what is the probability of rolling a $5$?', '["$\\frac{13}{18}$", "$\\frac{5}{18}$", "$\\frac{1}{18}$", "$\\frac{17}{18}$"]'::jsonb, 3, null),
  ('3a26793b-754b-5739-9a01-8f75fcebdd3d', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'If $5x = 8$, what is the value of $15x$?', '["$24$", "$\\frac{8}{3}$", "$120$", "$8$"]'::jsonb, 4, null),
  ('04b0836f-401c-5f5c-ad73-bb615e884d46', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'A number $f$ is $125%$ greater than a positive number $g$. A number $h$ is $40%$ less than the number $f$. The number $h$ is how many times the number $g$?', '["$1.35$", "$1.85$", "$0.90$", "$0.54$"]'::jsonb, 5, null),
  ('09b4e62e-7484-59a5-a2e8-9ec432b71b40', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'The function $f$ is defined by $f(x) = -\frac{5}{12}x + 9$. What is the slope of the graph of $y = f(x)$ in the $xy$- plane?', '["$-9$", "$5$", "$\\frac{1}{12}$", "$-\\frac{5}{12}$"]'::jsonb, 6, null),
  ('43dea692-78a4-5616-ab88-97525fd418a3', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'Line $k$ is defined by $y = -3x + 17$. Line $j$ is perpendicular to line $k$ in the $xy$-plane. What is the slope of line $j$?', '["$3$", "$-\\frac{1}{3}$", "$-3$", "$\\frac{1}{3}$"]'::jsonb, 7, null),
  ('cad95a14-1740-548b-8757-395957e6b655', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'What is the $y$-coordinate of the $y$-intercept of the graph of $y = 156(24)^{x}$ in the $xy$-plane?', '["$156$", "$3,744$", "$24$", "$1$"]'::jsonb, 8, null),
  ('2c52017e-4d8d-5c0d-ab80-6e78b3c2d545', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'For the values $j$ and $k$, the ratio of $j$ to $k$ is $9$ to $5$. If $j$ is multiplied by $12$, what is $k$ multiplied by in order to maintain the same ratio?', '[]'::jsonb, 9, null),
  ('1ff1098c-cf31-5878-98e6-0e2d2192fe3b', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'In the figure shown, triangle $CAE$ is similar to triangle $CBD$. The measure of angle $CBD$ is $47°$, and $AE = 19(BD)$. What is the measure of angle $CAE$?', '["$47°$", "$893°$", "$66°$", "$19°$"]'::jsonb, 10, '![figure](/q/sep26/003.webp)'),
  ('2d3e5852-2ced-58a8-b2d1-823adc3f0ed4', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'The expression $(4x + 3)(x + 6)$ can be written in the form $ax^{2} + bx + c$, where $a$, $b$, and $c$ are constants. What is the value of $a + b + c$?', '[]'::jsonb, 11, null),
  ('364dfa7d-7647-525a-aba3-71b25dc68421', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'An angle has a measure of $\frac{7π}{20}$ radians. What is the measure of the angle in degrees?', '[]'::jsonb, 12, null),
  ('5dd20b28-edaa-5fab-8bbf-592ddd1bbaab', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'A farmer gave two groups of chickens different types of chicken feed for six weeks to measure the effect on egg production. The lists give the number of eggs collected from each chicken in each of the two groups.
Group G: $9,15,17,17,22$
Group H: $15,17,17,22$
Which statement correctly compares the median number of eggs collected for group G and the median number of eggs collected for group H?', '["There is not enough information to compare the median number of eggs collected for group G and the median number of eggs collected for group H.", "The median number of eggs collected for group G is less than the median number of eggs collected for group H.", "The median number of eggs collected for group G is greater than the median number of eggs collected for group H.", "The median number of eggs collected for group G is equal to the median number of eggs collected for group H."]'::jsonb, 13, null),
  ('c2b5fb4d-c435-529f-8d4c-5b758dcca570', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', '$\sqrt{26} =\sqrt{\frac{1}{x}}$
What is the solution to the given equation?', '["$\\frac{1}{26}$", "$26$", "$676$", "$\\frac{1}{676}$"]'::jsonb, 14, null),
  ('f0ea9548-e702-50fc-bfb8-1aeafc087541', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'For a certain isotope, at the end of every 31-year period, the mass of a sample of the isotope has decayed to half its mass at the beginning of the 31-year period.
The function $s(t) = 320(0.5)^{\frac{t}{31}}$ gives the approximate mass of this isotope, in grams, that remains $t$ years after a 320-gram sample starts to decay. Which statement is the best interpretation of $s(4 \cdot$ $31) = 20$ in this context?', '["The mass of the sample is approximately 4 grams 20 31-year periods after the sample starts to decay.", "The mass of the sample is approximately 4 grams 20 years after the sample starts to decay.", "The mass of the sample is approximately 20 grams 4 31-year periods after the sample starts to decay.", "The mass of the sample is approximately 20 grams 4 years after the sample starts to decay."]'::jsonb, 15, null),
  ('f5f6cf68-b4f3-524f-b4da-af1f9c3c618b', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'The graph of the polynomial function $f$ in the $xy$-plane, where $y = f(x)$, passes through the point $(9,6)$. What is the value of $f(9)$?', '["$15$", "$54$", "$9$", "$6$"]'::jsonb, 16, null),
  ('410efae0-edda-5b3b-81d0-94ae1d14420c', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'The product of a positive number $x$ and the number that is $6$ more than $x$ is $247$. What is the value of $x$ ?', '[]'::jsonb, 17, null),
  ('3941bdb4-3b53-5c80-b8b9-5611e646b248', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'Object A has a mass of $k$ hectograms. The mass, in hectograms, of object B is $135%$ of the mass of object A. The positive difference between the mass of object B and the mass of object A is $98$ hectograms. What is the value of $k$?', '[]'::jsonb, 18, null),
  ('1fa27962-64c3-5087-b7f5-c4283688d7bb', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'For the linear function $f$, $f(3) = 19$ and $f(7) = 3$. Which equation defines $f$?', '["$f(x) = \\frac{1}{4}x - 2$", "$f(x) = -4x + 31$", "$f(x) = -\\frac{1}{4}x + 20$", "$f(x) = -4x + 35$"]'::jsonb, 19, null),
  ('c0387209-2205-568e-8bdb-99a950dc1db0', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'In triangle $QRS$ shown, $QR < RS$. Which expression represents the length of line segment $QS$?', '["$24\\cos Q$", "$\\frac{24}{\\sin Q}$", "$\\frac{24}{\\cos Q}$", "$24\\sin Q$"]'::jsonb, 20, '![figure](/q/sep26/004.webp)'),
  ('2d4be29d-fe4b-5600-83ea-0d3be39106c5', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'A moving truck rental company charges its customers \$140 for the first hour of renting a truck and \$72 for each additional hour, plus the cost of gas used. Which equation represents this situation, where $y$ is the total cost, in dollars, of renting a truck from this company for $x$ hours, $w$ is the cost, in dollars, of gas used, and $x \ge 1$?', '["$y = 140 + 72 + w$", "$y = 140 + 72x + w$", "$y = 72(x - 1) + w$", "$y = 140 + 72(x - 1) + w$"]'::jsonb, 21, null),
  ('96359ee3-2e3f-57d8-b41a-30d24ea9d830', '53250d9d-fec6-5eb0-b8a8-b2231e953e85', 'The line models the possible combinations of the number of small shelves, $x$, and the number of large shelves, $y$, assembled by a worker in $840$ minutes. It takes the worker a fixed amount of time to assemble each small shelf and a different fixed amount of time to assemble each large shelf. How long, in minutes, does it take the worker to assemble each large shelf?', '["$10$", "$84$", "$140$", "$60$"]'::jsonb, 22, '![figure](/q/sep26/005.webp)')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('8860cd01-f1b9-5cf4-94a2-2b469baa5229', 0, null, '$52 \times 37 = 1,924$ square centimeters.'),
  ('adbb25bd-baa8-5464-82c5-73bb4601d732', null, array['556']::text[], '$f(80) = 7(80) - 4 = 556$.'),
  ('295bef8a-e569-5a30-b3da-07b5c74a8627', 2, null, 'One of 18 equally likely faces: $\frac{1}{18}$.'),
  ('3a26793b-754b-5739-9a01-8f75fcebdd3d', 0, null, '$15x = 3(5x) = 3(8) = 24$.'),
  ('04b0836f-401c-5f5c-ad73-bb615e884d46', 0, null, '$f = 2.25g$ and $h = 0.6f = 1.35g$.'),
  ('09b4e62e-7484-59a5-a2e8-9ec432b71b40', 3, null, 'In $y = mx + b$ form the slope is $-\frac{5}{12}$.'),
  ('43dea692-78a4-5616-ab88-97525fd418a3', 3, null, 'Perpendicular slope is the negative reciprocal of $-3$: $\frac{1}{3}$.'),
  ('cad95a14-1740-548b-8757-395957e6b655', 0, null, 'At $x = 0$: $156(24)^{0} = 156$.'),
  ('2c52017e-4d8d-5c0d-ab80-6e78b3c2d545', null, array['12']::text[], 'To keep $\frac{j}{k}$ the same, both must be multiplied by the same number, 12.'),
  ('1ff1098c-cf31-5878-98e6-0e2d2192fe3b', 0, null, 'In similar triangles, angle $CAE$ corresponds to angle $CBD$: $47°$.'),
  ('2d3e5852-2ced-58a8-b2d1-823adc3f0ed4', null, array['49']::text[], '$(4x + 3)(x + 6) = 4x^{2} + 27x + 18$, so $a + b + c = 49$.'),
  ('364dfa7d-7647-525a-aba3-71b25dc68421', null, array['63']::text[], '$\frac{7π}{20} \cdot \frac{180}{π} = 63$ degrees.'),
  ('5dd20b28-edaa-5fab-8bbf-592ddd1bbaab', 3, null, 'Both medians are 17 (G: middle value 17; H: average of 17 and 17).'),
  ('c2b5fb4d-c435-529f-8d4c-5b758dcca570', 0, null, 'Squaring gives $26 = \frac{1}{x}$, so $x = \frac{1}{26}$.'),
  ('f0ea9548-e702-50fc-bfb8-1aeafc087541', 2, null, '$t = 4 \cdot 31$ is four 31-year periods, and $s = 20$ grams.'),
  ('f5f6cf68-b4f3-524f-b4da-af1f9c3c618b', 3, null, 'The point $(9, 6)$ on the graph means $f(9) = 6$.'),
  ('410efae0-edda-5b3b-81d0-94ae1d14420c', null, array['13']::text[], '$x(x + 6) = 247$ gives $(x - 13)(x + 19) = 0$; the positive solution is $13$.'),
  ('3941bdb4-3b53-5c80-b8b9-5611e646b248', null, array['280']::text[], '$1.35k - k = 0.35k = 98$, so $k = 280$.'),
  ('1fa27962-64c3-5087-b7f5-c4283688d7bb', 1, null, 'Slope $\frac{3 - 19}{7 - 3} = -4$; $19 = -4(3) + b$ gives $b = 31$.'),
  ('c0387209-2205-568e-8bdb-99a950dc1db0', 1, null, '$RS = 24$ is opposite angle $Q$ and $QS$ is the hypotenuse: $QS = \frac{24}{\sin Q}$.'),
  ('2d4be29d-fe4b-5600-83ea-0d3be39106c5', 3, null, '\$140 for the first hour plus \$72 for each of the other $x - 1$ hours, plus gas $w$.'),
  ('96359ee3-2e3f-57d8-b41a-30d24ea9d830', 1, null, 'The line meets the $y$-axis at 10: 10 large shelves take 840 minutes, so 84 minutes each.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

