insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('59416975-cca8-54ff-924a-55af76055252', 'PeaklyTest Sep 2026 · Math · Module 2', 'Math', 'Math, Module 2 of the Sep 2026 PeaklyTest · 22 questions · 35 minutes', 35, 113, true, 'PeaklyTest Sep 2026 · Math', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('9ca64b45-12b0-52e9-99e1-97cee5d3c1d1', '59416975-cca8-54ff-924a-55af76055252', 'A restaurant can seat up to $126$ people for an event using tables of two different sizes. The inequality $6S + 9L \le 126$ represents this situation, where $S$ is the number of small tables and $L$ is the number of large tables used for an event. What is the best interpretation of $6$ in this context?', '["The restaurant can hold at most $6$ large tables.", "The restaurant can hold at most $6$ small tables.", "Each small table can seat $6$ people.", "Each large table can seat $6$ people."]'::jsonb, 1, null),
  ('ec1fa007-72b1-51f3-b025-6ce97c5e161a', '59416975-cca8-54ff-924a-55af76055252', 'The scatterplot shows the relationship between two variables, $x$ and $y$. A line of best fit is also shown. Which of the following is closest to the slope of this line of best fit?', '["$-4.2$", "$1.4$", "$4.2$", "$-1.4$"]'::jsonb, 2, '![figure](/q/sep26/006.webp)'),
  ('ea06e9db-54d3-51ab-acd9-e892152d6396', '59416975-cca8-54ff-924a-55af76055252', 'If $3(2t - 7) + t = 24 + 5t$, what is the value of $2t$?', '[]'::jsonb, 3, null),
  ('b1350789-a9e9-5f3b-a90d-587ce1552fe2', '59416975-cca8-54ff-924a-55af76055252', 'The function $j$ is defined by $j(x) = \frac{8x+4}{5p}$, and the function $k$ is defined by $k(x) = \frac{j(x)p}{x+2}$, where $p$ is a positive constant. What is the value of $k(7)$?', '["$\\frac{28}{5}$", "$\\frac{4}{3}$", "$\\frac{20}{3}$", "$\\frac{8}{5}$"]'::jsonb, 4, null),
  ('30c26f91-e84f-54c3-9f3c-a5f4b267c56c', '59416975-cca8-54ff-924a-55af76055252', 'The solution to the system of equations $2x + 7y = 5$ and $6x - 3y = 39$ is $(x,y)$. What is the value of $8x - 6y$?', '[]'::jsonb, 5, null),
  ('bc3ce122-c7e8-5d66-99d3-d6ecf76786e3', '59416975-cca8-54ff-924a-55af76055252', 'An environmental scientist studies the decomposition of paper bags when the bags are placed in an environment with a certain type of bacteria. The exponential function $f(x) = 640(0.92)^{x}$ gives the estimated remaining mass, in grams, of the paper bags $x$ days after they are placed in this environment, where $0 \le x \le 28$.
If this function is graphed in the $xy$-plane, where $y = f(x)$, which statement is the best interpretation of the point $(2,541.70)$ on the graph?', '["The estimated remaining mass of the paper bags $2$ days after they are placed in this environment is $541.70$ grams.", "The estimated remaining mass of the paper bags $2$ days after they are placed in this environment is $541.70$ grams less than it was the day before.", "The estimated remaining mass of the paper bags $541.70$ days after they are placed in this environment is $2$ grams.", "The estimated remaining mass of the paper bags after they are placed in this environment is decreasing by $541.70$ grams per day."]'::jsonb, 6, null),
  ('3d66c0eb-4681-5546-9c44-364b2e730108', '59416975-cca8-54ff-924a-55af76055252', '$5x^{2} = p$
In the given equation, $p$ is a constant. The equation has no real solution. Which of the following could be the value of $p$?', '["$60$", "$-75$", "$35$", "$10$"]'::jsonb, 7, null),
  ('b7bf154c-d03f-58cf-a6ee-7a990fb9c7f0', '59416975-cca8-54ff-924a-55af76055252', 'The solution to the system of equations $x^{2} + y + 11 = 11$ and $14x + 49 - y = 0$ is $(x,y)$. What is the value of $x$?', '["$7$", "$-7$", "$-49$", "$14$"]'::jsonb, 8, null),
  ('4f196661-826d-5d67-82ca-3638e47f6540', '59416975-cca8-54ff-924a-55af76055252', 'When several resistors are connected in series in a circuit, the total resistance of the circuit is the sum of the resistances of these resistors. A certain circuit consists of $8$ resistors connected in series, where the resistance of each resistor is positive.
This circuit has a total resistance of $104$ ohms. The total resistance of $3$ resistors in this circuit is $69$ ohms. Which inequality best represents all possible values of the resistance $x$, in ohms, of one of the other $5$ resistors in this circuit?', '["$35 < x < 69$", "$0 < x < 35$", "$0 < x < 7$", "$35 < x < 104$"]'::jsonb, 9, null),
  ('5ffccaa4-710b-56f9-8a64-986a1a3b0098', '59416975-cca8-54ff-924a-55af76055252', '$G(x) = \frac{7}{4}(x - 250) + 28$
The function $G$ gives the temperature, in degrees on a laboratory scale G, that corresponds to a temperature of $x$ kelvins. If a temperature increased by $16.80$ kelvins, by how much did the temperature increase, in degrees G?', '["$29.40$", "$437.00$", "$465.00$", "$57.40$"]'::jsonb, 10, null),
  ('7332ebed-636b-5e0e-b02f-a84c7cf6cac1', '59416975-cca8-54ff-924a-55af76055252', 'Which system of linear equations has no solution?', '["$-5x + 7y = 3$; $10x - 14y = 8$", "$-5x + 7y = -3$; $5x - 7y = 3$", "$5x - 7y = 3$; $8x + 4y = 6$", "$5x - 7y = 3$; $-15x + 21y = -9$"]'::jsonb, 11, null),
  ('ab41ade1-09c7-5cc6-9278-313d7020a849', '59416975-cca8-54ff-924a-55af76055252', 'What is the $x$-intercept of the graph of $px + 18y = 3$ in the $xy$-plane, where $p$ is a positive constant?', '["$(p,0)$", "$(\\frac{3}{p},0)$", "$(\\frac{p}{18},0)$", "$(\\frac{1}{18},0)$"]'::jsonb, 12, null),
  ('7c348bd8-11df-5cf3-a854-0f1f30ca47e8', '59416975-cca8-54ff-924a-55af76055252', 'In the $xy$-plane, an equation of circle A is $(x + 4)^{2} + (y - 11)^{2} = 361$. Circle B is obtained by shifting circle A $6$ units to the right and $4$ units down. Which equation represents circle B?', '["$(x + 10)^{2} + (y - 7)^{2} = 361$", "$(x - 2)^{2} + (y - 7)^{2} = 361$", "$(x + 10)^{2} + (y - 15)^{2} = 361$", "$(x - 2)^{2} + (y - 15)^{2} = 361$"]'::jsonb, 13, null),
  ('edbb03e7-4836-5087-a70b-51a62276b565', '59416975-cca8-54ff-924a-55af76055252', 'A right square pyramid has a height of $12$ inches and a volume of $324$ cubic inches. What is the perimeter, in inches, of the base of this pyramid?', '[]'::jsonb, 14, null),
  ('e997c5ea-4a00-5ae1-81c6-d0bea466b8c3', '59416975-cca8-54ff-924a-55af76055252', '$5xy + 8xt - 22yt = 0$
In the given equation, $x$ and $y$ are positive and $x < y$. Which equation correctly expresses $t$ in terms of $x$ and $y$?', '["$t = \\frac{xy}{4(y-x)}$", "$t = \\frac{1}{4}$", "$t = \\frac{5xy}{8x-22y}$", "$t = \\frac{5xy}{22y-8x}$"]'::jsonb, 15, null),
  ('40a0fdf0-8f15-58b5-bd62-aa08f5201b51', '59416975-cca8-54ff-924a-55af76055252', '$f(x) = (1.06)^{3-5x}$
The function $f$ is defined by the given equation. The equation can be rewritten as $f(x) = a(1 - \frac{p}{100})^{x}$ , where $a$ and $p$ are constants. Which of the following is closest to the value of $p$?', '["$75$", "$52$", "$25$", "$18$"]'::jsonb, 16, null),
  ('d1d45288-313b-58ff-9387-8649fcda9352', '59416975-cca8-54ff-924a-55af76055252', 'For a function $f$, the value of $f(x)$ is multiplied by $3$ for every increase of $1$ in the value of $x$. When $x =$ $0$, $f(x) = 7$. Which of the following equations defines $f$?', '["$f(x) = 7(3x)$", "$f(x) = 7(3)^{x}$", "$f(x) = 3(7)^{x}$", "$f(x) = 7 + 3x$"]'::jsonb, 17, null),
  ('db275a4f-19c0-5418-91dd-b4992cb5ec66', '59416975-cca8-54ff-924a-55af76055252', 'In triangle $PQR$, the measure of angle $P$ is $(4x + 17)°$, the measure of angle $Q$ is $(5x + 16)°$, $PQ = 6$, and $QR = 6$.
Side $PR$ is extended through point $R$ to point $S$. The measure of angle $QRS$ is $y°$. What is the value of $y$?', '[]'::jsonb, 18, null),
  ('8bd763f8-c7b0-572e-acc4-ee735149e526', '59416975-cca8-54ff-924a-55af76055252', 'A right square pyramid has a height of $15$ centimeters (cm). A second right square pyramid has a height of $30$ centimeters. The area of the base of each pyramid is $100$ cm².
Which of the following is closest to the difference in the surface area of the second pyramid and the surface area of the first pyramid, in cm²?', '["$315$", "$506$", "$292$", "$214$"]'::jsonb, 19, null),
  ('d3bdaae6-cb92-5d98-ae44-ebeff086e9f2', '59416975-cca8-54ff-924a-55af76055252', 'The function $f$ is defined by $f(x) = \frac{∣x∣}{a} - 12$, where $a < 0$. What is the product of $f(14a)$ and $f(5a)$?', '[]'::jsonb, 20, null),
  ('387c639b-c1b4-591a-9499-52e82385719e', '59416975-cca8-54ff-924a-55af76055252', '$234$ is $p%$ greater than $18$. What is the value of $p$?', '["$1,200$", "$1,300$", "$216$", "$234$"]'::jsonb, 21, null),
  ('3773727e-654a-5ed9-b9c8-e4717fa0c110', '59416975-cca8-54ff-924a-55af76055252', 'Which expression is a factor of $y^{2}(x - 4) - 49(x - 4)^{3}$?', '["$y(x - 4)$", "$y + x - 4$", "$y + 7x - 28$", "$(x - 7)(x - 4)$"]'::jsonb, 22, null)
