insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('9ca64b45-12b0-52e9-99e1-97cee5d3c1d1', 2, null, '$S$ counts small tables, so 6 is the number of people each small table seats.'),
  ('ec1fa007-72b1-51f3-b025-6ce97c5e161a', 3, null, 'The line falls from about 12.6 at $x = 0$ to 0 at $x = 9$: slope about $-1.4$.'),
  ('ea06e9db-54d3-51ab-acd9-e892152d6396', null, array['45']::text[], '$6t - 21 + t = 24 + 5t$ gives $2t = 45$.'),
  ('b1350789-a9e9-5f3b-a90d-587ce1552fe2', 1, null, '$k(x) = \frac{8x + 4}{5(x + 2)}$, so $k(7) = \frac{60}{45} = \frac{4}{3}$.'),
  ('30c26f91-e84f-54c3-9f3c-a5f4b267c56c', null, array['54']::text[], 'Solving gives $x = 6$ and $y = -1$, so $8x - 6y = 48 + 6 = 54$.'),
  ('bc3ce122-c7e8-5d66-99d3-d6ecf76786e3', 0, null, '$x = 2$ days and $f(2) ≈ 541.70$ grams remaining.'),
  ('3d66c0eb-4681-5546-9c44-364b2e730108', 1, null, '$x^{2} = \frac{p}{5}$ has no real solution only when $p < 0$: $-75$.'),
  ('b7bf154c-d03f-58cf-a6ee-7a990fb9c7f0', 1, null, '$y = -x^{2}$, so $x^{2} + 14x + 49 = 0$, $(x + 7)^{2} = 0$ and $x = -7$.'),
  ('4f196661-826d-5d67-82ca-3638e47f6540', 1, null, 'The other five resistors total $104 - 69 = 35$ ohms, each positive, so $0 < x < 35$.'),
  ('5ffccaa4-710b-56f9-8a64-986a1a3b0098', 0, null, '$G$ changes by $\frac{7}{4}$ per kelvin: $\frac{7}{4}(16.80) = 29.40$.'),
  ('7332ebed-636b-5e0e-b02f-a84c7cf6cac1', 0, null, 'Dividing the second equation by $-2$ gives $-5x + 7y = -4$, parallel to $-5x + 7y = 3$.'),
  ('ab41ade1-09c7-5cc6-9278-313d7020a849', 1, null, '$y = 0$ gives $px = 3$, so $x = \frac{3}{p}$.'),
  ('7c348bd8-11df-5cf3-a854-0f1f30ca47e8', 1, null, 'The center moves from $(-4, 11)$ to $(2, 7)$; the radius is unchanged.'),
  ('edbb03e7-4836-5087-a70b-51a62276b565', null, array['36']::text[], '$\frac{1}{3}s^{2}(12) = 324$ gives $s = 9$, so the perimeter is $36$.'),
  ('e997c5ea-4a00-5ae1-81c6-d0bea466b8c3', 3, null, '$t(8x - 22y) = -5xy$, so $t = \frac{5xy}{22y - 8x}$.'),
  ('40a0fdf0-8f15-58b5-bd62-aa08f5201b51', 2, null, '$(1.06)^{-5x} = (1.06^{-5})^{x} ≈ 0.747^{x}$, a decrease of about 25% per unit.'),
  ('d1d45288-313b-58ff-9387-8649fcda9352', 1, null, 'Start at 7 and multiply by 3 for each 1: $f(x) = 7(3)^{x}$.'),
  ('db275a4f-19c0-5418-91dd-b4992cb5ec66', null, array['123']::text[], '$PQ = QR$ makes angles $P$ and $R$ equal: $2(4x + 17) + 5x + 16 = 180$ gives $x = 10$, so angle $R = 57°$ and $y = 180 - 57 = 123$.'),
  ('8bd763f8-c7b0-572e-acc4-ee735149e526', 2, null, 'Slant heights $\sqrt{15^{2} + 5^{2}} ≈ 15.81$ and $\sqrt{30^{2} + 5^{2}} ≈ 30.41$; lateral areas $≈ 316.2$ and $608.3$ differ by about $292$.'),
  ('d3bdaae6-cb92-5d98-ae44-ebeff086e9f2', null, array['442']::text[], 'With $a < 0$, $\frac{|14a|}{a} = -14$ and $\frac{|5a|}{a} = -5$: $(-26)(-17) = 442$.'),
  ('387c639b-c1b4-591a-9499-52e82385719e', 0, null, '$\frac{234 - 18}{18} = 12$, a 1,200% increase.'),
  ('3773727e-654a-5ed9-b9c8-e4717fa0c110', 2, null, '$(x - 4)(y^{2} - 49(x - 4)^{2}) = (x - 4)(y - 7x + 28)(y + 7x - 28)$.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;
